impl<T: gx::Real> Vector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t3 = x[3] * x[3];
        let t4 = (-x[1]).mul_add(x[1], t0);
        let t5 = x[2].mul_add(x[2], t3);
        let t6 = t4 - t5;
        t6
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (23 mul, 12 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Vector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t6 = t0 * t2;
        let t8 = t1 * t1;
        let t10 = t1 * t3;
        let t13 = t3 * t3;
        let t14 = t0.mul_add(t0, t8);
        let t15 = t2.mul_add(t2, t13);
        let t16 = t14 + t15;
        let t17 = t1.mul_add(t2, t10);
        let t18 = t2.mul_add(t3, t17);
        let t19 = t0.mul_add(t1, t6);
        let t20 = t0.mul_add(t3, t19);
        let t21 = t18 - t20;
        let t23 = t21.mul_add(T::from_i64(2), t16);
        let t24 = t23.recip();
        let t25 = t0 * t24;
        let t28 = t3 * t24;
        let t29 = (-t1).mul_add(t24, t25);
        let t30 = t2.mul_add(t24, t28);
        let t31 = t29 - t30;
        let t32 = x[0] * t31;
        let t33 = x[1] * t31;
        let t34 = x[2] * t31;
        let t35 = x[3] * t31;
        Vector::from_coeffs([t32, t33, t34, t35])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p3 = x[3] * x[3];
        let p4 = (-x[1]).mul_add(x[1], p0);
        let p5 = x[2].mul_add(x[2], p3);
        let p6 = p4 - p5;
        let s0 = (p6).abs().sqrt().recip();
        let t0 = x[0] * s0;
        let t1 = x[1] * s0;
        let t2 = x[2] * s0;
        let t3 = x[3] * s0;
        gx::Unit::new_unchecked(Vector::from_coeffs([t0, t1, t2, t3]))
    }

}

impl<T: gx::Coef> gx::NewtonStep for Vector<(), T> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t3 = x[3] * x[3];
        let t4 = (-x[1]).mul_add(x[1], t0);
        let t5 = x[2].mul_add(x[2], t3);
        let t6 = t4 - t5;
        let t8 = (-t6).mul_add(T::from_ratio(1, 3), T::from_i64(1));
        let t9 = x[0] * t8;
        let t10 = x[1] * t8;
        let t11 = x[2] * t8;
        let t12 = x[3] * t8;
        let t13 = t9 * T::from_ratio(3, 2);
        let t14 = t10 * T::from_ratio(3, 2);
        let t15 = t11 * T::from_ratio(3, 2);
        let t16 = t12 * T::from_ratio(3, 2);
        Vector::from_coeffs([t13, t14, t15, t16])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

