impl<T: gx::Real> Bivector<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t4 = x[4] * x[4];
        let t6 = x[3].mul_add(x[3], t4);
        let t7 = x[5].mul_add(x[5], t6);
        let t8 = x[0].mul_add(x[0], t1);
        let t9 = x[2].mul_add(x[2], t8);
        let t10 = t7 - t9;
        t10
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (76 mul, 49 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Bivector<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t3 = x[3] * x[3];
        let t4 = x[4] * x[4];
        let t5 = x[5] * x[5];
        let t6 = x[0] * x[3];
        let t7 = x[1] * x[4];
        let t8 = x[2] * x[5];
        let t11 = t0 * t2;
        let t16 = t6 * t8;
        let t17 = t1 * t1;
        let t18 = t1 * t2;
        let t19 = t1 * t3;
        let t24 = t2 * t3;
        let t26 = t2 * t5;
        let t29 = t3 * t5;
        let t30 = t4 * t4;
        let t31 = t4 * t5;
        let t33 = t0.mul_add(t0, t17);
        let t34 = t2.mul_add(t2, t33);
        let t35 = t3.mul_add(t3, t30);
        let t36 = t5.mul_add(t5, t35);
        let t37 = t34 + t36;
        let t38 = t0.mul_add(t1, t11);
        let t39 = t0.mul_add(t3, t18);
        let t40 = t38 + t39;
        let t41 = t1.mul_add(t4, t26);
        let t42 = t3.mul_add(t4, t29);
        let t43 = t41 + t42;
        let t44 = t40 + t43;
        let t45 = (-t0).mul_add(t4, t31);
        let t46 = t0.mul_add(t5, t19);
        let t47 = t45 - t46;
        let t48 = t1.mul_add(t5, t24);
        let t49 = t2.mul_add(t4, t48);
        let t50 = t47 - t49;
        let t51 = t44 + t50;
        let t53 = t6.mul_add(t7, t16);
        let t54 = t7.mul_add(t8, t53);
        let t56 = t51.mul_add(T::from_i64(2), t37);
        let t57 = t54.mul_add(T::from_i64(8), t56);
        let t58 = t57.recip();
        let t59 = t0 * t58;
        let t62 = t1.mul_add(t58, t59);
        let t63 = t2.mul_add(t58, t62);
        let t64 = t3 * t58;
        let t67 = t4.mul_add(t58, t64);
        let t68 = t5.mul_add(t58, t67);
        let t69 = t6 * t58;
        let t70 = t7 * t58;
        let t71 = t8 * t58;
        let t72 = t69 + t70;
        let t74 = t71.mul_add(T::from_ratio(1, 2), t72);
        let t75 = t69 + t71;
        let t77 = t70.mul_add(T::from_ratio(1, 2), t75);
        let t78 = t70 + t71;
        let t80 = t78.mul_add(T::from_i64(2), t69);
        let t81 = t59 - t68;
        let t82 = t64 - t63;
        let t83 = x[1] * t58;
        let t84 = x[2] * t58;
        let t85 = x[0] * t58;
        let t86 = x[1] * t83;
        let t87 = x[2] * t84;
        let t89 = t5 * t85;
        let t91 = x[3] * t80;
        let t93 = x[1] * t82;
        let t94 = x[4] * t77;
        let t96 = x[2] * t82;
        let t97 = x[5] * t74;
        let t100 = x[3] * t87;
        let t101 = x[3] * t68;
        let t102 = x[1] * t77;
        let t104 = x[4] * t81;
        let t106 = x[2] * t74;
        let t107 = x[5] * t81;
        let t108 = x[0].mul_add(t63, t91);
        let t109 = t4.mul_add(t85, t89);
        let t110 = t108 - t109;
        let t111 = t5.mul_add(t83, t93);
        let t113 = t94.mul_add(T::from_i64(2), -t111);
        let t114 = t4.mul_add(t84, t96);
        let t116 = t97.mul_add(T::from_i64(2), -t114);
        let t117 = x[3].mul_add(t86, t100);
        let t118 = x[0].mul_add(t80, t101);
        let t119 = t117 - t118;
        let t120 = x[4].mul_add(t87, t104);
        let t122 = (-t102).mul_add(T::from_i64(2), t120);
        let t123 = x[5].mul_add(t86, t107);
        let t125 = (-t106).mul_add(T::from_i64(2), t123);
        Bivector::from_coeffs([t110, t113, t116, t119, t122, t125])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p4 = x[4] * x[4];
        let p7 = x[1] * x[4];
        let p9 = x[3].mul_add(x[3], p4);
        let p10 = x[5].mul_add(x[5], p9);
        let p11 = x[0].mul_add(x[0], p1);
        let p12 = x[2].mul_add(x[2], p11);
        let p13 = p10 - p12;
        let p14 = x[0].mul_add(x[3], p7);
        let p15 = x[2].mul_add(x[5], p14);
        let p16 = p15 * T::from_i64(2);
        let [s0, s1] = gx::study::rsqrt(-1, p13, p16);
        let t1 = x[3] * s1;
        let t3 = x[4] * s1;
        let t5 = x[5] * s1;
        let t7 = x[3] * s0;
        let t9 = x[4] * s0;
        let t11 = x[5] * s0;
        let t12 = x[0].mul_add(s0, t1);
        let t13 = x[1].mul_add(s0, t3);
        let t14 = x[2].mul_add(s0, t5);
        let t15 = (-x[0]).mul_add(s1, t7);
        let t16 = (-x[1]).mul_add(s1, t9);
        let t17 = (-x[2]).mul_add(s1, t11);
        gx::Unit::new_unchecked(Bivector::from_coeffs([t12, t13, t14, t15, t16, t17]))
    }

    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B` with `BÂ²` a Study number.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Even<(), T>> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let p1 = x[1] * x[1];
        let p4 = x[4] * x[4];
        let p7 = x[1] * x[4];
        let p9 = x[0].mul_add(x[0], p1);
        let p10 = x[2].mul_add(x[2], p9);
        let p11 = x[3].mul_add(x[3], p4);
        let p12 = x[5].mul_add(x[5], p11);
        let p13 = p10 - p12;
        let p14 = x[0].mul_add(x[3], p7);
        let p15 = x[2].mul_add(x[5], p14);
        let p16 = p15 * T::from_i64(2);
        let p17 = -p16;
        let [c0, c1, s0, s1] = gx::study::exp_coeffs(-1, p13, p17);
        let t1 = x[3] * s1;
        let t3 = x[4] * s1;
        let t5 = x[5] * s1;
        let t7 = x[3] * s0;
        let t9 = x[4] * s0;
        let t11 = x[5] * s0;
        let t12 = x[0].mul_add(s0, t1);
        let t13 = x[1].mul_add(s0, t3);
        let t14 = x[2].mul_add(s0, t5);
        let t15 = (-x[0]).mul_add(s1, t7);
        let t16 = (-x[1]).mul_add(s1, t9);
        let t17 = (-x[2]).mul_add(s1, t11);
        gx::Unit::new_unchecked(Even::from_coeffs([c0, t12, t13, t14, t15, t16, t17, c1]))
        })
    }

}

impl<T: gx::Coef> gx::NewtonStep for Bivector<(), T> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[1] * x[1];
        let t2 = x[3] * x[3];
        let t3 = t0 + t1;
        let t4 = T::from_i64(3) - t2;
        let t5 = t3 + t4;
        let t6 = x[2] * x[2];
        let t7 = x[4] * x[4];
        let t8 = x[5] * x[5];
        let t9 = t6 - t7;
        let t10 = t9 - t8;
        let t11 = x[0] * x[3];
        let t12 = x[1] * x[4];
        let t13 = x[2] * x[5];
        let t14 = t11 + t12;
        let t16 = t13.mul_add(T::from_ratio(3, 2), t14);
        let t17 = t11 + t13;
        let t19 = t12.mul_add(T::from_ratio(3, 2), t17);
        let t20 = t12 + t13;
        let t22 = t20.mul_add(T::from_ratio(2, 3), t11);
        let t23 = t0 + t10;
        let t24 = t5 + t6;
        let t26 = x[0] * t23;
        let t29 = x[1] * t24;
        let t32 = x[2] * t24;
        let t37 = x[3] * t10;
        let t40 = x[4] * t23;
        let t44 = x[5] * t5;
        let t45 = x[0].mul_add(t1, t26);
        let t47 = (-x[3]).mul_add(t22, x[0]);
        let t48 = t47 * T::from_ratio(3, 2);
        let t49 = t45.mul_add(T::from_ratio(1, 2), t48);
        let t50 = (-x[1]).mul_add(t8, t29);
        let t51 = t50 * T::from_ratio(1, 2);
        let t52 = (-x[4]).mul_add(t19, t51);
        let t53 = (-x[2]).mul_add(t7, t32);
        let t54 = t53 * T::from_ratio(1, 2);
        let t55 = (-x[5]).mul_add(t16, t54);
        let t56 = x[3].mul_add(t1, t37);
        let t57 = (-x[3]).mul_add(t2, t56);
        let t59 = x[0].mul_add(t22, x[3]);
        let t60 = t59 * T::from_ratio(3, 2);
        let t61 = t57.mul_add(T::from_ratio(1, 2), t60);
        let t62 = (-x[4]).mul_add(t2, t40);
        let t63 = t62 * T::from_ratio(1, 2);
        let t65 = x[1].mul_add(t19, t63);
        let t66 = x[4].mul_add(T::from_ratio(3, 2), t65);
        let t67 = (-x[5]).mul_add(t7, t44);
        let t68 = (-x[5]).mul_add(t8, t67);
        let t69 = t68 * T::from_ratio(1, 2);
        let t70 = x[2].mul_add(t16, t69);
        Bivector::from_coeffs([t49, t52, t55, t61, t66, t70])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

