impl<T: gx::Real> Pseudoscalar<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = -t0;
        t1
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, `~x (x ~x)â»Â¹` (4 mul, 0 add, 1 div).
    #[inline(always)]
    pub fn inverse(self) -> Pseudoscalar<(), T> {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t2 = x[0] * t1;
        let t3 = t2.recip();
        let t4 = t1 * t3;
        let t5 = -t4;
        Pseudoscalar::from_coeffs([t5])
    }

    /// Scaled to a unit versor, `(x ~x)^(-1/2) x`, so that `x ~x = 1` (`Â±1` when the norm is negative).
    #[inline(always)]
    pub fn normalized(self) -> gx::Unit<Self> {
        let x = self.c;
        let p0 = x[0] * x[0];
        let p1 = -p0;
        let s0 = (p1).abs().sqrt().recip();
        let t0 = x[0] * s0;
        gx::Unit::new_unchecked(Pseudoscalar::from_coeffs([t0]))
    }

    /// The exponential: for `x = a + b B` with `BÂ² = -1`, `e^a (C(b) + S(b) B)` with `C, S` the
    /// cosine and sine (`BÂ² = -1`), the hyperbolic ones (`+1`) or `1, b` (`0`). A `Phasor`, not a
    /// `gx::Unit`: `x ~x` need not be 1.
    #[inline]
    pub fn exp(self) -> Phasor<(), T> {
        let (a, b) = (T::zero(), self.c[0]);
        let e = a.exp();
        Phasor::from_coeffs([e * (b.cos()), e * (b.sin())])
    }

}

impl<T: gx::Coef> gx::NewtonStep for Pseudoscalar<(), T> {
    /// `(3 â x ~x) x / 2`: one Newton step towards `x ~x = 1`, without a square root.
    #[inline(always)]
    fn newton_step(self) -> Self {
        let x = self.c;
        let t0 = x[0] * x[0];
        let t1 = x[0] * t0;
        let t3 = x[0] * T::from_ratio(3, 2);
        let t4 = t1.mul_add(T::from_ratio(1, 2), t3);
        Pseudoscalar::from_coeffs([t4])
    }

    #[inline(always)]
    fn note_renormalize() {
        T::note_renormalize();
    }
}

