    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t2 = x[2] * x[2];
        let t4 = x[4] * x[4];
        let t6 = x[6] * x[6];
        let t7 = x[7] * x[7];
        let t8 = x[0].mul_add(x[0], t4);
        let t9 = x[5].mul_add(x[5], t6);
        let t10 = t8 + t9;
        let t11 = x[1].mul_add(x[1], t2);
        let t12 = x[3].mul_add(x[3], t7);
        let t13 = t11 + t12;
        let t14 = t10 - t13;
        t14
    }

    /// The norm, `sqrt(|norm_squared|)`.
