        let t17 = t15 + t16;
        let t18 = t11 + t14;
        let t19 = t18 + T::from_i64(3);
        let t20 = t17 - t19;
        let t21 = t2 + t3;
        let t23 = t4.mul_add(T::from_ratio(3, 2), t21);
        let t24 = x[1] * x[1];
        let t25 = x[4] * x[4];
        let t26 = t25 - t10;
        let t27 = t15 + t26;
        let t28 = t14 + t24;
        let t29 = t28 + T::from_i64(3);
        let t30 = t27 - t29;
        let t31 = t1 + t5;
        let t33 = t31.mul_add(T::from_ratio(2, 3), t0);
        let t34 = t2 + t4;
        let t36 = t34.mul_add(T::from_ratio(2, 3), t3);
        let t37 = t9 + t13;
        let t38 = t25 - t11;
        let t39 = t37 + t38;
        let t40 = t39 - t29;
        let t43 = x[0] * t10;
        let t44 = x[0] * t11;
        let t46 = x[0] * t12;
        let t49 = x[1] * t24;
        let t52 = x[2] * t10;
        let t54 = x[5] * t36;
        let t55 = x[3] * t11;
        let t58 = x[1] * t8;
        let t60 = x[4] * t20;
        let t61 = x[2] * t36;
