impl<T: gx::Real> gx::Log<Bivector<(), T>> for gx::Unit<Even<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Bivector<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p1 = x[2] * x[2];
        let p4 = x[5] * x[5];
        let p7 = x[2] * x[5];
        let p9 = x[1].mul_add(x[1], p1);
        let p10 = x[3].mul_add(x[3], p9);
        let p11 = x[4].mul_add(x[4], p4);
        let p12 = x[6].mul_add(x[6], p11);
        let p13 = p10 - p12;
        let p14 = x[1].mul_add(x[4], p7);
        let p15 = x[3].mul_add(x[6], p14);
        let p16 = p15 * T::from_i64(2);
        let p17 = -p16;
        let [h0, h1] = gx::study::log_coeffs(-1, (x[0], x[7]), (p13, p17));
        let t1 = x[4] * h1;
        let t3 = x[5] * h1;
        let t5 = x[6] * h1;
        let t7 = x[4] * h0;
        let t9 = x[5] * h0;
        let t11 = x[6] * h0;
        let t12 = x[1].mul_add(h0, t1);
        let t13 = x[2].mul_add(h0, t3);
        let t14 = x[3].mul_add(h0, t5);
        let t15 = (-x[1]).mul_add(h1, t7);
        let t16 = (-x[2]).mul_add(h1, t9);
        let t17 = (-x[3]).mul_add(h1, t11);
        Bivector::from_coeffs([t12, t13, t14, t15, t16, t17])
        })
    }
}

